$ErrorActionPreference = "Stop"

$RepoRoot = Join-Path $HOME "Intellect-Media"
$Python = Join-Path $RepoRoot ".venv\Scripts\python.exe"
$Repair = Join-Path $RepoRoot "runtime\foundation_repair.py"

if (-not (Test-Path $RepoRoot)) {
    throw "Intellect-Media repository not found: $RepoRoot"
}

if (-not (Test-Path $Python)) {
    throw "Python virtual environment not found: $Python"
}

Set-Location $RepoRoot
New-Item -ItemType Directory -Path "runtime" -Force | Out-Null

$Encoded = ""
[System.IO.File]::WriteAllBytes(
    $Repair,
    [System.Convert]::FromBase64String($Encoded)
)

Write-Host "Running state migration..." -ForegroundColor Cyan
& $Python $Repair

if ($LASTEXITCODE -ne 0) {
    throw "Foundation repair failed."
}

Write-Host ""
Write-Host "=== REPAIR COMPLETE ===" -ForegroundColor Green
git status --short
